import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`youtube-thumbnail-design`,heroTitle:`Design scroll-stopping thumbnails in minutes`,heroSubtitle:`Perplexity Computer studies top-performing videos, analyzes competitor thumbnails, and generates thumbnail concepts with title pairings — automatically.`,inputUrlCta:`Analyze my channel`,inputUrlPlaceholder:`youtube.com/@yourchannel`,inputUrlPrefill:`Go to {url} and perform a deep YouTube channel and thumbnail analysis. 1) Identify the channel's niche, content style, and branding elements — colors, fonts, face usage, text overlays, and recurring visual patterns. 2) Find the top 20 highest-performing videos in this niche (across this channel and competitors) and analyze what makes their thumbnails work — facial expressions, color contrast, text placement, layout composition, and click-through patterns. 3) Break down competitor thumbnail strategies — who's winning clicks and why. 4) Based on these insights, generate 5 thumbnail concepts for upcoming videos. For each concept, provide: a detailed design prompt (suitable for Canva or AI image tools), recommended color palette, text overlay copy, facial expression or subject direction, layout sketch description, and 3 title variations optimized for CTR. 5) Include a thumbnail style guide summarizing the winning patterns for this niche — what to do and what to avoid.`,heroOverlaySteps:[`Studying your channel's branding, niche, and visual style`,`Analyzing top-performing thumbnails across your niche`,`Breaking down competitor layouts, colors, and text patterns`,`Thumbnail concepts, design prompts, and title pairings — ready to create`],generatingSteps:[`Visiting {url} to extract your channel branding, niche, and top videos`,`Designing an agent to analyze winning thumbnails across your niche and competitors`,`Configuring thumbnail concept generation with design prompts and title pairings`,`Setting up your thumbnail style guide and CTR optimization engine`],featureSectionTitle:`From channel URL to click-worthy thumbnails`,featureCardTitles:[`Connects to your creator stack`,`Outputs you can design with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Canva, Google Drive, Google Sheets, Notion, Trello — Computer delivers thumbnail concepts and style guides straight into the tools you already use.`,`Thumbnail concepts with design prompts. Color palettes and layout breakdowns. Title pairings optimized for CTR. A niche-specific thumbnail style guide.`],capabilitySectionTitle:`Your thumbnail designer, on autopilot`,capabilitySectionSubtitle:`Paste your channel, step away, come back to scroll-stopping thumbnail concepts.`,capabilityCards:[{title:`Niche Analysis`,description:`Computer can study top-performing videos across your niche — breaking down the thumbnail patterns, colors, faces, and text that drive the highest click-through rates.`},{title:`Competitor Breakdown`,description:`Computer can analyze competitor thumbnails side by side — identifying what's winning clicks and where your channel can stand out visually.`},{title:`Concept Generation`,description:`Computer can generate thumbnail concepts with detailed design prompts, color palettes, text overlays, and layout directions — ready for Canva or any design tool.`},{title:`Connect Your Tools`,description:`Computer can push thumbnail briefs and style guides to Canva, Google Drive, Notion, and Trello — so your design workflow stays in one place.`},{title:`Learn Your Style`,description:`Computer can remember your brand colors, past thumbnails, and top performers — so every new concept builds on what's already working for your channel.`},{title:`Track & Refresh`,description:`Computer can monitor your video performance and flag when thumbnail trends shift in your niche — so your designs never fall behind.`}]});export{t as default};
